export const HOA11_CHUONG1_HANDBOOK = [{"title": "1. Khái Niệm Phản Ứng Thuận Nghịch & Trạng Thái Cân Bằng", "icon": "⚖️", "content": ["Phản ứng thuận nghịch là phản ứng xảy ra theo hai chiều trái ngược nhau trong cùng điều kiện: aA + bB ⇌ cC + dD.", "Trạng thái cân bằng hóa học là trạng thái của phản ứng thuận nghịch khi tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch (v<sub>t</sub> = v<sub>n</sub>).", "Cân bằng hóa học là cân bằng động, các chất phản ứng và sản phẩm luôn tồn tại đồng thời trong hệ."]}, {"title": "2. Hằng Số Cân Bằng Nồng Độ (Kc)", "icon": "🔢", "content": ["Biểu thức hằng số cân bằng: K<sub>c</sub> = ([C]<sup>c</sup> &times; [D]<sup>d</sup>) / ([A]<sup>a</sup> &times; [B]<sup>b</sup>) (chỉ áp dụng cho chất khí và chất tan trong dung dịch, không tính chất rắn).", "K<sub>c</sub> chỉ phụ thuộc vào bản chất của phản ứng và <b>nhiệt độ</b>, không phụ thuộc vào nồng độ ban đầu của các chất."]}, {"title": "3. Nguyên Lí Chuyển Dịch Cân Bằng Le Chatelier", "icon": "🔄", "content": ["Một phản ứng thuận nghịch đang ở trạng thái cân bằng khi chịu tác động từ bên ngoài (nồng độ, nhiệt độ, áp suất) thì cân bằng sẽ chuyển dịch theo chiều làm <b>giảm tác động</b> đó.", "<b>Nồng độ:</b> Tăng nồng độ chất nào thì cân bằng chuyển dịch theo chiều làm giảm nồng độ chất đó (chiều tiêu thụ).", "<b>Áp suất:</b> Tăng áp suất chung của hệ thì cân bằng chuyển dịch theo chiều làm giảm số mol khí (và ngược lại). Nếu tổng số mol khí hai vế bằng nhau thì áp suất không ảnh hưởng.", "<b>Nhiệt độ:</b> Tăng nhiệt độ thì cân bằng chuyển dịch theo chiều thu nhiệt (&Delta;<sub>r</sub>H<sup>0</sup> > 0); giảm nhiệt độ thì chuyển dịch theo chiều tỏa nhiệt (&Delta;<sub>r</sub>H<sup>0</sup> < 0)."]}, {"title": "4. Thuyết Acid – Base Của Brønsted – Lowry", "icon": "💧", "content": ["<b>Acid:</b> Là chất có khả năng cho proton (H<sup>+</sup>).", "<b>Base:</b> Là chất có khả năng nhận proton (H<sup>+</sup>).", "<b>Chất lưỡng tính:</b> Vừa có khả năng cho proton vừa có khả năng nhận proton (VD: H<sub>2</sub>O, HCO<sub>3</sub><sup>-</sup>, HSO<sub>3</sub><sup>-</sup>, H<sub>2</sub>PO<sub>4</sub><sup>-</sup>, Al(OH)<sub>3</sub>, Zn(OH)<sub>2</sub>)."]}, {"title": "5. Thang Đo pH & Chuẩn Độ Acid – Base", "icon": "🧪", "content": ["Tích số ion của nước ở 25 &deg;C: K<sub>w</sub> = [H<sup>+</sup>] &times; [OH<sup>-</sup>] = 1,0 &times; 10<sup>-14</sup>.", "<b>Công thức tính pH:</b> pH = -log[H<sup>+</sup>]; pOH = -log[OH<sup>-</sup>]; pH + pOH = 14.", "Môi trường acid: [H<sup>+</sup>] > 10<sup>-7</sup> M &rArr; pH < 7. Môi trường trung tính: [H<sup>+</sup>] = 10<sup>-7</sup> M &rArr; pH = 7. Môi trường base: [H<sup>+</sup>] < 10<sup>-7</sup> M &rArr; pH > 7.", "Chuẩn độ acid – base xác định nồng độ dung dịch dựa trên phản ứng trung hòa: n<sub>H<sup>+</sup></sub> = n<sub>OH<sup>-</sup></sub> &rArr; C<sub>1</sub>V<sub>1</sub> = C<sub>2</sub>V<sub>2</sub>."]}];

const STORAGE_PREFIX = 'hoa11_c1_';

export function calculateChuong1ExamScore(exam: Chuong1Exam, answers: Record<string, any>): {
  score: number;
  part1Score: number;
  part2Score: number;
  part3Score: number;
  correctCount: number;
  totalQuestions: number;
} {
  if (!exam || !exam.questions) {
    return { score: 0, part1Score: 0, part2Score: 0, part3Score: 0, correctCount: 0, totalQuestions: 0 };
  }

  let part1Score = 0;
  let part2Score = 0;
  let part3Score = 0;
  let correctCount = 0;

  exam.questions.forEach((q) => {
    const userAns = answers[q.id];

    if (q.part === 1) {
      const correctOpt = q.options?.find((o) => o.isCorrect)?.letter || q.correctAnswer;
      if (userAns && userAns === correctOpt) {
        part1Score += (q.points || 0.25);
        correctCount += 1;
      }
    } else if (q.part === 2) {
      if (userAns && typeof userAns === 'object' && q.options) {
        let correctSub = 0;
        q.options.forEach((opt) => {
          const userSubVal = userAns[opt.id || opt.letter?.toLowerCase()];
          const isActuallyTrue = Boolean(opt.isCorrect);
          if (userSubVal === 'true' && isActuallyTrue) correctSub++;
          else if (userSubVal === 'false' && !isActuallyTrue) correctSub++;
        });

        if (correctSub === 1) part2Score += 0.1;
        else if (correctSub === 2) part2Score += 0.25;
        else if (correctSub === 3) part2Score += 0.5;
        else if (correctSub === 4) {
          part2Score += 1.0;
          correctCount += 1;
        }
      }
    } else if (q.part === 3) {
      if (userAns !== undefined && userAns !== null && String(userAns).trim() !== '') {
        const normUser = String(userAns).trim().toLowerCase().replace(',', '.');
        const normCorrect = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
        if (normUser === normCorrect) {
          part3Score += (q.points || 0.25);
          correctCount += 1;
        }
      }
    }
  });

  const rawTotal = part1Score + part2Score + part3Score;
  const score = Math.round(rawTotal * 100) / 100;

  return {
    score,
    part1Score: Math.round(part1Score * 100) / 100,
    part2Score: Math.round(part2Score * 100) / 100,
    part3Score: Math.round(part3Score * 100) / 100,
    correctCount,
    totalQuestions: exam.questions.length
  };
}

export function getChuong1UserProgress() {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}progress`);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    completedSets: {},
    starredQuestions: [],
    examScores: {},
    totalXP: 0,
    rankTitle: 'Tân Binh Hóa Học',
    lastActive: new Date().toISOString()
  };
}

export function getChuong1ExamHistory(): Chuong1ExamAttempt[] {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}exam_history`);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return [];
}

export function saveChuong1ExamAttempt(attempt: Chuong1ExamAttempt) {
  try {
    const hist = getChuong1ExamHistory();
    hist.unshift(attempt);
    if (hist.length > 50) hist.pop();
    localStorage.setItem(`${STORAGE_PREFIX}exam_history`, JSON.stringify(hist));

    const p = getChuong1UserProgress();
    const prev = p.examScores[attempt.examId] || { score: 0, date: '', attempts: 0 };
    p.examScores[attempt.examId] = {
      score: Math.max(prev.score, attempt.score),
      date: attempt.completedAt,
      attempts: prev.attempts + 1
    };
    p.totalXP = (p.totalXP || 0) + Math.round(attempt.score * 20);
    p.rankTitle = getRankTitle(p.totalXP);
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(p));
  } catch (e) {}
}

export function saveChuong1ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  try {
    const p = getChuong1UserProgress();
    const prev = p.examScores[examId] || { score: 0, date: '', attempts: 0 };
    p.examScores[examId] = {
      score: Math.max(prev.score, score),
      date: new Date().toISOString(),
      attempts: prev.attempts + 1
    };
    p.totalXP = (p.totalXP || 0) + Math.round(score * 20);
    p.rankTitle = getRankTitle(p.totalXP);
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(p));
  } catch (e) {}
}

export function shuffleChuong1Exam(exam: Chuong1Exam): Chuong1Exam {
  if (!exam || !exam.questions) return exam;
  const cloned: Chuong1Question[] = JSON.parse(JSON.stringify(exam.questions));
  const p1 = cloned.filter(q => q.part === 1);
  const p2 = cloned.filter(q => q.part === 2);
  const p3 = cloned.filter(q => q.part === 3);

  const shuffleArray = <T>(arr: T[]): T[] => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArray(p1).map(q => {
    if (q.options && q.options.length > 0) {
      const origCorrectOpt = q.options.find(o => o.isCorrect) || q.options.find(o => o.letter === q.correctAnswer);
      const origCorrectText = origCorrectOpt?.text;
      const shuffledOptions = shuffleArray(q.options);
      const letters = ['A', 'B', 'C', 'D'];
      shuffledOptions.forEach((opt, idx) => { opt.letter = letters[idx]; });
      const newCorrectOpt = shuffledOptions.find(o => (origCorrectText && o.text === origCorrectText) || o.isCorrect);
      const newCorrectLetter = newCorrectOpt?.letter || 'A';
      shuffledOptions.forEach(opt => { opt.isCorrect = (opt.letter === newCorrectLetter); });
      return { ...q, options: shuffledOptions, correctAnswer: newCorrectLetter };
    }
    return q;
  });

  const shuffledP2 = shuffleArray(p2).map(q => {
    if (q.options && q.options.length > 0) {
      const shuffledOptions = shuffleArray(q.options);
      const letters = ['a', 'b', 'c', 'd'];
      shuffledOptions.forEach((opt, idx) => { opt.letter = letters[idx]; });
      return { ...q, options: shuffledOptions };
    }
    return q;
  });

  const shuffledP3 = shuffleArray(p3);

  const finalQuestions = [...shuffledP1, ...shuffledP2, ...shuffledP3].map((q, idx) => ({
    ...q,
    displayNumber: idx + 1
  }));

  return { ...exam, questions: finalQuestions };
}

export function getRankTitle(xp: number): string {
  if (xp >= 5000) return '👑 Thủ Khoa Hóa 11';
  if (xp >= 3000) return '💎 Bậc Thầy Cân Bằng Hóa Học';
  if (xp >= 1500) return '🥇 Chuyên Gia Hóa Học';
  if (xp >= 500) return '🥈 Nhà Thực Nghiệm';
  return '🥉 Tân Binh Hóa Học';
}

export const getChuong1RankTitle = getRankTitle;
export const getChuong2RankTitle = getRankTitle;
